// Confere o pedido e escolhe o caminho. O ambiente vem do workflow da Kira (nó "Ambiente atual"), nunca da IA.
// A IA só guarda rascunhos e consulta; publicar só vem do comando /instagram <número>, mandado pelo dono.
const AMBIENTE = 'NEGOCIOS';
const ACOES_DA_KIRA = ['rascunho', 'rascunhos', 'posts'];
const LIMITE_LEGENDA = 2200;
const LIMITE_HASHTAGS = 30;

const e = $input.first().json;
const texto = (v) => String(v ?? '').trim();
const inteiro = (v) => Math.max(0, Math.floor(Number(v) || 0));
const pedido = {
  acao: texto(e.acao).toLowerCase(),
  origem: texto(e.origem).toLowerCase(),
  ambiente: texto(e.ambiente).toUpperCase(),
  user_id: texto(e.user_id),
  chat_id: texto(e.chat_id),
  legenda: texto(e.legenda),
  imagem_id: inteiro(e.imagem_id),
  rascunho_id: inteiro(e.rascunho_id),
  quantidade: Math.min(10, Math.max(1, inteiro(e.quantidade) || 5)),
};
const recusar = (mensagem) => [{ json: { ...pedido, rota: 'recusar', ok: false, mensagem } }];

if (pedido.acao === 'publicar') {
  // O rascunho já nasceu no modo Negócios; o comando do dono publica em qualquer ambiente.
  if (pedido.origem !== 'comando') {
    return recusar('A publicação no Instagram só acontece quando o dono manda /instagram <número>. Mostre o rascunho e peça para ele mandar o comando.');
  }
  if (!pedido.rascunho_id) return recusar('Me diga qual rascunho publicar, por exemplo: /instagram 3');
  if (!pedido.user_id) return recusar('Não consegui identificar quem pediu a publicação.');
  return [{ json: { ...pedido, rota: 'publicar' } }];
}
if (pedido.ambiente !== AMBIENTE) {
  return recusar('O Instagram da loja é do ambiente Negócios. Diga ao dono, em uma frase, que ele pode trocar dizendo "modo negócios". Não use nem invente dados do Instagram aqui.');
}
if (!ACOES_DA_KIRA.includes(pedido.acao)) return recusar('Ação inválida. Use rascunho, rascunhos ou posts.');
if (!pedido.user_id) return recusar('Não consegui identificar o dono.');
if (pedido.acao === 'rascunho') {
  if (!pedido.imagem_id) {
    return recusar('Todo post do Instagram precisa de uma imagem. Gere ou edite uma com gerar_imagem (ou use o número de uma foto do dono) e passe imagem_id.');
  }
  if (!pedido.legenda) return recusar('Faltou a legenda do post.');
  if (pedido.legenda.length > LIMITE_LEGENDA) {
    return recusar(`A legenda tem ${pedido.legenda.length} caracteres e o Instagram aceita até ${LIMITE_LEGENDA}. Encurte e tente de novo.`);
  }
  const hashtags = (pedido.legenda.match(/#[\p{L}\p{N}_]+/gu) || []).length;
  if (hashtags > LIMITE_HASHTAGS) return recusar(`A legenda tem ${hashtags} hashtags e o Instagram aceita até ${LIMITE_HASHTAGS}.`);
}
return [{ json: { ...pedido, rota: pedido.acao } }];

