// Confere se o rascunho pode ser publicado agora. "publicando" travado há mais de 10 minutos pode tentar de novo.
const pedido = $('Validar pedido').first().json;
const r = $input.first().json ?? {};
const numero = pedido.rascunho_id;
const parado = r.status === 'publicando' && Date.now() - new Date(r.updatedAt).getTime() > 10 * 60 * 1000;
let mensagem = '';
if (!r.id) mensagem = `Não encontrei o rascunho ${numero} do Instagram. Peça para eu preparar o post de novo.`;
else if (r.status === 'publicado') mensagem = `O rascunho ${numero} já foi publicado no Instagram${r.permalink ? `: ${r.permalink}` : '.'}`;
else if (!['pendente', 'erro', 'publicando'].includes(r.status)) mensagem = `O rascunho ${numero} não pode ser publicado (situação: ${r.status || 'desconhecida'}).`;
else if (r.status === 'publicando' && !parado) mensagem = `O rascunho ${numero} está sendo publicado agora. Espere um pouco e veja no Instagram.`;
else if (!(Number(r.imagem_id) > 0) || !String(r.legenda ?? '').trim()) mensagem = `O rascunho ${numero} está sem imagem ou sem legenda. Peça para eu preparar o post de novo.`;
return [{ json: { ...r, rascunho_id: numero, pode: !mensagem, ok: !mensagem, mensagem } }];

// Cria uma chave aleatória para o link público da imagem. O Instagram baixa a imagem por esse link durante a
// publicação; a chave só vale enquanto o rascunho está "publicando" e é apagada logo depois.
// O endereço do n8n sai do próprio n8n (o mesmo dos webhooks), sem ficar escrito aqui.
const r = $input.first().json;
const CAMINHO = 'kira-instagram-imagem';
let chave = '';
try {
  chave = (crypto.randomUUID() + crypto.randomUUID()).replace(/-/g, '');
} catch (e) {
  chave = '';
}
if (chave.length < 32) {
  const letras = 'abcdefghijklmnopqrstuvwxyz0123456789';
  chave = Array.from({ length: 48 }, () => letras[Math.floor(Math.random() * letras.length)]).join('');
}
const base = String($execution.resumeUrl ?? '').replace(/\/webhook-waiting\/.*$/, '');
if (!/^https:\/\//.test(base)) throw new Error('Não descobri o endereço público (https) do n8n para o link da imagem.');
return [{ json: { ...r, token_imagem: chave, link_imagem: `${base}/webhook/${CAMINHO}?t=${chave}` } }];

// Confere se o Instagram terminou de processar a imagem antes de publicar (tenta por até 1 minuto).
const MAX_TENTATIVAS = 20;
const r = $input.first().json ?? {};
const codigo = String(r.status_code ?? '');
const tentativa = $runIndex + 1;
let situacao = 'esperar';
let motivo = '';
if (codigo === 'FINISHED') situacao = 'pronto';
else if (['ERROR', 'EXPIRED', 'PUBLISHED'].includes(codigo)) {
  situacao = 'falhou';
  motivo = `O Instagram não aceitou o post: ${r.status || codigo}`;
} else if (tentativa >= MAX_TENTATIVAS) {
  situacao = 'falhou';
  motivo = 'O Instagram demorou demais para processar a imagem. Tente de novo em alguns minutos.';
}
return [{ json: { situacao, status_code: codigo, tentativa, ...(motivo ? { error: { message: motivo } } : {}) } }];

// Traduz o erro do Facebook/Instagram em uma frase curta (sem chaves nem links).
const pedido = $('Validar pedido').first().json;
const item = $input.first().json ?? {};
function motivoDoErro(v) {
  const e = v?.error ?? v;
  for (const c of [e?.description, e?.message, typeof e === 'string' ? e : '']) {
    if (!c) continue;
    const s = String(c);
    const ini = s.indexOf('{');
    const fim = s.lastIndexOf('}');
    let trecho = ini >= 0 && fim > ini ? s.slice(ini, fim + 1) : '';
    for (let i = 0; trecho && i < 2; i++) {
      try {
        const j = JSON.parse(trecho);
        const g = j.error ?? j;
        return String(g.error_user_msg || g.message || s);
      } catch (x) {
        trecho = trecho.replace(/\\"/g, '"').replace(/\\\\/g, '\\');
      }
    }
    return s;
  }
  return 'erro desconhecido';
}
let motivo = motivoDoErro(item)
  .replace(/access_token=[^&\s"]+/gi, 'access_token=…')
  .replace(/EAA[A-Za-z0-9]{20,}/g, '…')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 300);
const DICAS = [
  [/aspect ratio|proporç/i, 'o formato da imagem não é aceito pelo Instagram'],
  [/could not be fetched|only photo or video|media type|URI/i, 'o Instagram não conseguiu baixar a imagem pelo link temporário'],
  [/permission|permiss/i, 'falta permissão no app da Meta'],
  [/session has expired|expired|invalid oauth|Error validating access token/i, 'a chave do Instagram venceu ou foi desligada; é preciso gerar outra'],
  [/limit|limite/i, 'o limite de publicações do dia foi atingido'],
];
const dica = DICAS.find(([re]) => re.test(motivo))?.[1];
return [{ json: { ...pedido, ok: false, motivo, dica: dica ?? '' } }];

// Resume a conta e os últimos posts. Devolve só números e textos curtos: nunca os links de paginação
// do Facebook, que carregam a chave de acesso.
const FUSO = 'America/Sao_Paulo';
const TIPOS = { IMAGE: 'foto', CAROUSEL_ALBUM: 'carrossel', VIDEO: 'vídeo' };
const conta = $input.first().json.instagram_business_account;
if (!conta || !conta.username) throw new Error('A Página do Facebook não tem uma conta do Instagram ligada.');
const quando = (iso) => {
  const d = new Date(String(iso ?? '').replace(/([+-]\d\d)(\d\d)$/, '$1:$2'));
  return isNaN(d) ? '' : DateTime.fromJSDate(d).setZone(FUSO).toFormat('dd/MM/yyyy HH:mm');
};
const curta = (s, n) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};
const posts = (conta.media?.data ?? []).map((p, i) => ({
  posicao: i + 1,
  data: quando(p.timestamp),
  tipo: p.media_product_type === 'REELS' ? 'reels' : TIPOS[p.media_type] ?? String(p.media_type ?? '').toLowerCase(),
  legenda: curta(p.caption, 150),
  curtidas: p.like_count ?? null,
  comentarios: p.comments_count ?? null,
  link: p.permalink ?? '',
}));
return [
  {
    json: {
      ok: true,
      conta: '@' + conta.username,
      seguidores: conta.followers_count ?? null,
      total_de_posts: conta.media_count ?? null,
      posts,
      observacao: 'Curtidas e comentários contam até agora. Alcance e visualizações ainda não estão liberados.',
    },
  },
];

// Lista os rascunhos do Instagram que ainda não foram publicados (os mais novos primeiro).
const PENDENTES = ['pendente', 'erro'];
const lista = $input
  .all()
  .map((item) => item.json)
  .filter((r) => r && r.id && PENDENTES.includes(r.status))
  .sort((a, b) => b.id - a.id)
  .slice(0, 10);
return [
  {
    json: {
      ok: true,
      total: lista.length,
      rascunhos: lista.map((r) => ({
        rascunho: r.id,
        imagem: Number(r.imagem_id) || 0,
        status: r.status === 'erro' ? 'falhou na última tentativa' : 'pendente',
        legenda: String(r.legenda ?? '').slice(0, 200),
        ...(r.erro ? { erro: String(r.erro).slice(0, 200) } : {}),
      })),
      mensagem: lista.length
        ? 'Para publicar um rascunho, o dono manda /instagram <número>.'
        : 'Não há rascunhos do Instagram esperando publicação.',
    },
  },
];

// O Instagram aceita fotos entre 4:5 (em pé) e 1,91:1 (deitada). Se a imagem passar disso, corta um pouco
// (até 12%) ou, se precisar cortar mais, completa com faixas para não perder a peça.
const MIN = 0.8;
const MAX = 1.91;
const CORTE_MAXIMO = 0.12;
const item = $input.first();
const largura = Number(item.json.size?.width) || 0;
const altura = Number(item.json.size?.height) || 0;
if (!largura || !altura) throw new Error('Não consegui ler o tamanho da imagem.');
let corteLargura = largura;
let corteAltura = altura;
let faixaLargura = 0;
let faixaAltura = 0;
const proporcao = largura / altura;
if (proporcao < MIN) {
  const ideal = Math.floor(largura / MIN);
  if (1 - ideal / altura <= CORTE_MAXIMO) corteAltura = ideal;
  else faixaLargura = Math.ceil((altura * MIN - largura) / 2);
} else if (proporcao > MAX) {
  const ideal = Math.floor(altura * MAX);
  if (1 - ideal / largura <= CORTE_MAXIMO) corteLargura = ideal;
  else faixaAltura = Math.ceil((largura / MAX - altura) / 2);
}
// Faixas escuras para fotos escuras e brancas para fotos claras.
const medias = ['Red', 'Green', 'Blue'].map((canal) => {
  const m = String(item.json['Channel Statistics']?.[canal]?.Mean ?? '').match(/\(([\d.]+)\)/);
  return m ? Number(m[1]) : 1;
});
const clara = medias.reduce((a, b) => a + b, 0) / medias.length >= 0.5;
return [
  {
    json: {
      largura,
      altura,
      corte_largura: corteLargura,
      corte_altura: corteAltura,
      corte_x: Math.floor((largura - corteLargura) / 2),
      corte_y: Math.floor((altura - corteAltura) / 2),
      faixa_largura: faixaLargura,
      faixa_altura: faixaAltura,
      cor_faixa: clara ? '#FFFFFF' : '#000000',
    },
    binary: item.binary,
  },
];
